cases.script:
cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
printf 'private-data' > data
cu shred -n 0 -z -x data

cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
printf 'private-data' > data
cu shred -n 0 -z -s 12 data

cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
s() { local rc=0; "$@" || rc=$?; echo "rc=$rc"; }
s cu numfmt abc; s cu numfmt 1 abc 3; s cu numfmt 1K; s cu numfmt 1e3; s cu numfmt 1.
s cu numfmt --invalid=fail abc 5; s cu numfmt --invalid=warn abc 5; s cu numfmt --invalid=ignore abc 5
s cu numfmt --from=si 1Kx; s cu numfmt --from=iec-i 1K; s cu numfmt 99999999999999999999
printf '1\nbad\n3\n' | s cu numfmt --to=iec

cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
s() { local rc=0; "$@" >/dev/null || rc=$?; echo "rc=$rc"; }
s cu numfmt --bogus; s cu numfmt --to=bogus 1; s cu numfmt --to=i 1; s cu numfmt --round=x 1
s cu numfmt --padding=0 1; s cu numfmt --format=%d 1; s cu numfmt --format='%f%f' 1; s cu numfmt --format=abc 1
s cu numfmt --field=0 1; s cu numfmt --field=3-1 1; s cu numfmt --field=1 --field=2 1; s cu numfmt -d ab 1
s cu numfmt --grouping --to=si 1; s cu numfmt --from-unit=0 1; s cu numfmt --header=0 1; s cu numfmt -x 1

cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
s() { local rc=0; "$@" || rc=$?; echo "rc=$rc"; }
printf 'x\n' > s; mkdir dd
s cu install -t nodir s; s cu install -t s s; s cu install -t dd -T s; s cu install -T s dd; ls -A dd

cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
printf '# a
# b
' | cu fmt -p '#'
printf '  // one two
  // three
code();
// four
' | cu fmt -w 12 --prefix=//
printf '> q1
>q2
plain  text
' | cu fmt -p '> '

cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
s() { local rc=0; "$@" || rc=$?; echo "rc=$rc"; }
printf 'a' | s cu tsort
printf 'a b\nb c\nc\n' | s cu tsort
printf 'a b c' > odd; s cu tsort odd
printf 'a\nb\n' | s cu tsort
